// CRES Academy acronym glossary. Every acronym used in the lessons, deep dives, cheat sheet, and questions.
// Rendered by the engine as hover links and as the cheat sheet's Acronyms section. Keys match whole words,
// case-sensitive, plurals allowed. Original wording. Fields: full, tip (one sentence), more (longer; blank line = paragraph).
window.FRA = window.FRA || {};
FRA.acronyms = {
  "AAMI": { full: "Association for the Advancement of Medical Instrumentation", tip: "The standards body for medical equipment and the sponsor of the technician credentials.", more: "AAMI publishes the equipment-management standards hospitals follow and the US adoption of IEC 60601. Its credentials institute, ACI, runs the radiology equipment specialist exam this course prepares you for." },
  "ABC": { full: "Automatic brightness control", tip: "The fluoroscopic feedback loop that holds image brightness by raising mA, kVp, or pulse width as the patient thickens.", more: "Automatic brightness control is why dose rate climbs on a large patient and in magnification modes: the system is defending image brightness, not dose. When a fluoroscope reads a high tabletop exposure rate, check its calibration and whether the operator left a magnification mode engaged." },
  "AC": { full: "Alternating current", tip: "Mains power that reverses direction, 60 Hz in the United States and 50 Hz in much of the world.", more: "Transformers only work on AC, which is why the autotransformer and step-up transformer sit on the incoming side of an imaging generator. The tube itself needs one-way current, so rectifiers convert AC to DC before the high voltage reaches the cathode." },
  "ACI": { full: "AAMI Credentials Institute", tip: "The body inside AAMI that writes and administers the certification exams.", more: "ACI sets each exam's content outline, eligibility, fees, and retake rules, and reports results as pass or fail." },
  "ACR": { full: "American College of Radiology", tip: "The body that accredits imaging facilities and publishes the phantoms and scoring that accreditation uses.", more: "ACR accreditation is required for mammography under federal law and is common for computed tomography, magnetic resonance, and ultrasound. Its phantoms set the pass marks a technician has to reach: for the mammography test object, four fibers, three speck groups, and three masses." },
  "ADC": { full: "Analog-to-digital converter", tip: "The stage that turns a detector's analog charge or voltage into the numbers an imaging computer can work with.", more: "Its bit depth sets how finely the signal is divided and its sampling rate sets how fast rows or channels can be read out. A converter or its voltage reference drifting shows up as banding or a shifted gray scale across a whole image rather than as a single bad pixel." },
  "ADT": { full: "Admit, discharge, transfer", tip: "The messages that tell every system who the patient is and where they are.", more: "The admit, discharge, and transfer feed keeps the scheduling system, the archive, and the chart matched to the same patient. When a modality cannot find a patient who was definitely registered, suspect this feed or the interface engine queue before the modality." },
  "AE": { full: "Application entity", tip: "A DICOM node, identified by its application entity title, address, and port.", more: "A modality must be configured with the archive's application entity title, address, and port, and the archive must know the modality's, or nothing transfers. The titles are case-sensitive, and a typo in one is the most common reason a newly installed room cannot send images." },
  "AEC": { full: "Automatic exposure control", tip: "Ionization chambers in front of the receptor that end the exposure once enough radiation has arrived.", more: "Automatic exposure control holds image density across patient thicknesses, so the operator picks kVp and lets the system choose the exposure length. It has a backup timer that must end the exposure at 6 s or 600 mAs, and testing it with lead over the cell is a standard quality control step." },
  "ALARA": { full: "As low as reasonably achievable", tip: "The radiation safety principle: the least dose that still answers the clinical question.", more: "In practice ALARA means time, distance, and shielding for staff, and for patients the lowest technique, the smallest field, the fewest exposures, and no avoidable repeats. Every protective feature on an imaging system exists to serve it." },
  "ANSI": { full: "American National Standards Institute", tip: "The United States body that accredits standards developers such as AAMI.", more: "A standard carrying both names means ANSI approved the process the developer followed. Equipment-management programs in hospitals are written against those standards." },
  "AP": { full: "Anteroposterior", tip: "A projection in which the beam enters the front of the body and exits the back.", more: "In an anteroposterior projection the patient faces the tube, supine or erect, and the receptor is behind them. It is the default for a supine patient, which is why portable and trauma work is full of it." },
  "BF": { full: "Body floating (applied part)", tip: "An applied part that touches the patient but not the heart, isolated from ground.", more: "Type BF parts are electrically floating with tighter leakage limits than type B: 100 microamps normal and 500 microamps single fault under IEC 60601-1. Monitoring leads and probes on imaging carts and interventional tables are typically this type." },
  "BMET": { full: "Biomedical equipment technician", tip: "The job title for the technician who inspects, maintains, and repairs clinical equipment.", more: "Full certification as a radiology equipment specialist is built on top of this work: the pathways all count years of full-time technician experience, and at least 40 percent of that experience over the last two years must be in the radiology specialty." },
  "BRH": { full: "Bureau of Radiological Health", tip: "The former federal office whose radiation-emitting product work now sits inside the FDA device center.", more: "The performance standards for diagnostic x-ray equipment began here, which is why older service manuals and exam questions still refer to it. The work is now carried by CDRH." },
  "CABT": { full: "Certified Associate in Biomedical Technology", tip: "The entry-level credential on the certification ladder, below the technician credential.", more: "It recognizes someone who has completed the schooling but not yet the required years of full-time work. The ladder continues through the general technician credential, the radiology equipment specialist credential, and the healthcare technology manager credential." },
  "CBET": { full: "Certified Biomedical Equipment Technician", tip: "The general technician credential, the usual step before specializing in imaging.", more: "It covers anatomy and physiology, electricity and electronics, public safety, equipment function, problem solving, and healthcare information technology across every kind of clinical device. The radiology specialist exam keeps those same domain names but reweights them toward imaging." },
  "CCD": { full: "Charge-coupled device", tip: "A solid-state sensor that turns light into charge, used in some digital mammography and camera chains.", more: "A charge-coupled device gives good spatial resolution for its size, which is why it appeared in early digital mammography and in fluoroscopic camera tubes' replacements. Flat-panel arrays have largely displaced it in new equipment." },
  "CDRH": { full: "Center for Devices and Radiological Health", tip: "The FDA center that regulates medical devices and radiation-emitting products.", more: "This is the office behind the federal performance standards in 21 CFR 1020, device clearance and approval, recalls, and medical device reporting. Mammography inspection and accreditation under federal law also run through it." },
  "CF": { full: "Cardiac floating (applied part)", tip: "An applied part isolated well enough for a direct connection to the heart.", more: "Type CF has the tightest leakage limits in IEC 60601-1: 10 microamps normal and 50 microamps single fault. Catheter-based connections in an interventional suite are this type, which is where microshock risk is highest." },
  "CFR": { full: "Code of Federal Regulations", tip: "The published body of United States federal rules; imaging performance standards sit in title 21, part 1020.", more: "When a question cites 21 CFR 1020, it means the federal performance standards for radiation-emitting products: leakage limits, timer and indicator requirements, collimation accuracy, and the fluoroscopic exposure rate limits." },
  "CHTM": { full: "Certified Healthcare Technology Manager", tip: "The management credential at the top of the technician certification ladder.", more: "It covers program management rather than bench work: staffing, budgets, regulatory compliance, risk, and vendor relationships. Many specialists move toward it after years of imaging service." },
  "CMMS": { full: "Computerized maintenance management system", tip: "The database of record for the equipment inventory, work orders, and maintenance history.", more: "It holds every device by control number with its risk class and interval, every work order with findings and readings, the due and overdue lists, recall tracking, and the reports a surveyor asks for. If the repair is not in the system, as far as an inspector is concerned it did not happen." },
  "CMS": { full: "Centers for Medicare and Medicaid Services", tip: "The federal agency whose conditions of participation a hospital must meet to be paid.", more: "It can survey a hospital directly or accept the survey of an accrediting organization it has granted deeming authority. Equipment maintenance requirements in those conditions are the reason maintenance strategies have to be documented and defended." },
  "CR": { full: "Computed radiography", tip: "Cassette-based digital imaging: a storage phosphor plate is exposed, read by a laser scanner, then erased and reused.", more: "The plate stores a latent image that the scanner's laser releases as light, which a photomultiplier reads line by line. Dust and scratches on the plate print on every image, an incomplete erase leaves a ghost of the previous exposure, and plates lose speed with age." },
  "CRCPD": { full: "Conference of Radiation Control Program Directors", tip: "Where state radiation control programs write their shared suggested regulations.", more: "States license and inspect x-ray equipment themselves, so their rules differ, but most start from this common text. It is why registration, survey intervals, and operator rules look similar from state to state without being identical." },
  "CRES": { full: "Certified Radiology Equipment Specialist", tip: "The ACI credential for technicians who service imaging equipment: 165 questions, 3 hours, offered in May and November.", more: "Full certification needs the technician pathway plus at least 40 percent of work experience in radiology over the last two years and 25 percent over five. Recertified every three years with continuing education." },
  "CsI": { full: "Cesium iodide", tip: "The scintillator that converts x-rays to light in indirect digital detectors and image intensifier inputs.", more: "Grown in needle-like columns, cesium iodide channels the light it makes toward the photodiode array below, which keeps the image sharp while absorbing a large share of the beam. Thallium-activated cesium iodide is the usual form in mammography and general radiographic detectors." },
  "CT": { full: "Computed tomography", tip: "Cross-sectional imaging made by rotating a tube and detector array around the patient and reconstructing slices.", more: "A slip ring carries power and data so rotation never stops, the couch moves during a helical scan, and pitch describes couch travel per rotation. Service work centers on table and laser alignment, detector and air calibrations, cooling, and the reconstruction computers." },
  "CTDI": { full: "Computed tomography dose index", tip: "The dose in one slice spread over a defined 10 cm length, so radiation delivered outside the chosen slice is counted.", more: "It is measured with a pencil ionization chamber in a standard phantom, usually by the medical physicist, and it appears on the dose report the archive stores. Multiplying it by the length scanned gives the dose length product." },
  "C-ECHO": { full: "DICOM verification service", tip: "The DICOM ping: it proves two nodes can open an association and talk.", more: "It is the first test whenever images will not move, because it checks the application entity titles, address, port, and firewall path in one step without sending patient data." },
  "C-STORE": { full: "DICOM storage service", tip: "The push that sends an image or series from a modality or workstation to another node.", more: "A modality that can verify a connection but cannot store usually has a mismatch in what the receiver accepts, or has run into a disk, licence, or permission limit at the archive." },
  "C-FIND": { full: "DICOM query service", tip: "A query that asks another node which studies match given criteria.", more: "It is what populates a search on a workstation and what a modality worklist query uses to pull scheduled patients. Returning nothing when studies plainly exist points at the query level or the attributes being matched." },
  "C-MOVE": { full: "DICOM retrieve service", tip: "A request asking a node to send matching studies to a named destination.", more: "This is how prior studies are retrieved for comparison. The destination has to be configured on the sending node, so a retrieve can fail for a workstation that queries perfectly well." },
  "DAP": { full: "Dose area product", tip: "Dose multiplied by the area of the beam, measured by a meter under the collimator.", more: "Because it counts the volume of tissue irradiated and not just the dose at a point, it is a better indicator of risk than dose alone, and it falls when the field is collimated even if the dose rate does not change. It is widely used to monitor fluoroscopic and interventional output." },
  "DBT": { full: "Digital breast tomosynthesis", tip: "Mammography that sweeps the tube through an arc and reconstructs thin slices.", more: "Separating overlapping tissue improves detection, at the cost of a moving gantry and an arc calibration that join the quality control list. The compression, detector, and automatic exposure control checks of conventional mammography all still apply." },
  "DC": { full: "Direct current", tip: "Current in one direction only; what an x-ray tube needs across its cathode and anode.", more: "Rectifiers turn the alternating supply into direct current so electrons always travel from filament to target. Without rectification the negative half-cycle would put voltage backward across the tube and destroy it." },
  "DHCP": { full: "Dynamic Host Configuration Protocol", tip: "The service that hands out addresses automatically; a 169.254 address means it could not be reached.", more: "Modalities and archives are usually given static addresses or reservations so they are always reachable at the same place. A device that self-assigns an address has a server, relay, or link problem, not an application problem." },
  "DI": { full: "Deviation index", tip: "How far an exposure landed from the target for that exam: the technologist's dose feedback number.", more: "Zero means the receptor got what the protocol intended, positive means more, negative means less. Tracking it finds both overexposure and the underexposed noisy images that get repeated, which is why it belongs in a dose review as much as the exposure index does." },
  "DICOM": { full: "Digital Imaging and Communications in Medicine", tip: "The standard for medical image formats and for the network services that move them.", more: "It defines the image object, the service-object pairs a node supports, and the association two nodes negotiate before anything transfers. Every modality, archive, and reading station in an imaging department speaks it, commonly on port 104 or 11112." },
  "DLP": { full: "Dose length product", tip: "The computed tomography dose index multiplied by the length scanned, so it grows with how much of the patient was covered.", more: "Because it scales with coverage, it is the better figure for comparing whole examinations, while the dose index compares scanner settings. Both are displayed at the console, recorded with the study, and reviewed against the protocol." },
  "DMM": { full: "Digital multimeter", tip: "The bench meter for voltage, current, and resistance at the test points a service manual names.", more: "Measure resistance and continuity only with the equipment off and capacitors discharged, and voltage only when the circuit must be live and the room is clear. On a continuity range, an over-limit reading means the path is open." },
  "DNA": { full: "Deoxyribonucleic acid", tip: "The molecule carrying a cell's instructions, and the target that makes ionizing radiation dangerous.", more: "A photon can damage it directly, or indirectly by splitting water into reactive fragments that attack it, and because the body is mostly water the indirect route does most of the harm. Cells that are dividing have the most exposed and the most consequential copies of it, which is why bone marrow, the gonads, and children are the most radiosensitive." },
  "DNS": { full: "Domain Name System", tip: "Turns names into addresses; if the address works and the name does not, it is this.", more: "Archives and interfaces are often configured by name, so a name resolution problem can stop transfers while everything else looks healthy. Testing by address and then by name separates the two in one step." },
  "DQE": { full: "Detective quantum efficiency", tip: "How much of the radiation reaching a detector becomes usable signal.", more: "A higher value means the same image quality at lower dose, which is why it is the headline number when detectors are compared. It varies with photon energy, so a detector that is excellent at one technique is not automatically better at another." },
  "DR": { full: "Digital radiography", tip: "Direct-capture digital imaging: the detector reads out electronically with no plate to carry to a reader.", more: "Indirect panels use a cesium iodide scintillator over an amorphous silicon transistor array; direct panels use amorphous selenium to make charge from x-rays without a light step. Both need offset, gain, and defective pixel calibration kept current." },
  "DSA": { full: "Digital subtraction angiography", tip: "A mask image taken before contrast is subtracted from the contrast run so only vessels remain.", more: "It needs a stationary patient and stable geometry, so any motion between mask and run leaves misregistration artifacts that look like disease. Table, tube, and detector motion faults therefore become image quality complaints." },
  "DVM": { full: "Digital voltmeter", tip: "A meter dedicated to voltage measurement; the pre-reading voltmeter on a console is one.", more: "An imaging console shows selected kVp on a voltmeter reading the autotransformer tap before any exposure is made. Never trust that display during quality control: verify the real tube potential with a non-invasive meter." },
  "EHR": { full: "Electronic health record", tip: "The longitudinal patient record shared across an organization, which the imaging report lands in.", more: "Clinicians read reports and open images from this record, so an interface fault between imaging and the record becomes a clinical complaint very quickly, even though every image was captured correctly." },
  "EI": { full: "Exposure index", tip: "The number a digital detector reports to say how much radiation it actually received.", more: "It replaces the old habit of judging exposure from how dark the film looked, because digital processing hides over and underexposure. Compared with the target for the exam it becomes the deviation index." },
  "EMI": { full: "Electromagnetic interference", tip: "Unwanted energy coupling between equipment; it works in both directions in an imaging suite.", more: "A scanner can disturb monitors and pumps nearby, and a noisy device inside a shielded room can spoil the image. Shielded rooms, filter panels, proper grounding, and cable routing are the defenses, and a propped door or bad penetration undoes all of them." },
  "EMR": { full: "Electronic medical record", tip: "The clinical chart inside one organization, where orders begin and reports arrive.", more: "An imaging order is placed here, scheduled by the information system, performed on the modality, and reported back here. Knowing that path tells you how wide a fault is when someone says the order is missing." },
  "ESD": { full: "Electrostatic discharge", tip: "A static spark that destroys or weakens electronic parts without leaving a mark.", more: "Detector boards, processor cards, and memory are all at risk. Use a wrist strap and a grounded mat, hold boards by the edges, and keep them in antistatic bags; a part damaged this way often fails days later, which makes it look like a different fault." },
  "FDA": { full: "Food and Drug Administration", tip: "The United States agency that regulates medical devices, including every radiation-emitting imaging system.", more: "It clears and approves devices, runs recalls and medical device reporting, publishes the federal performance standards for radiation-emitting products, and administers the federal mammography program through its device center." },
  "GFCI": { full: "Ground fault circuit interrupter", tip: "A device that opens the circuit on a small imbalance between hot and neutral, tripping at 4 to 6 mA.", more: "It protects people, not equipment, and is required in wet locations. A receptacle that trips every time a particular device is plugged in is reporting a real leakage path in that device, not a nuisance." },
  "GI": { full: "Gastrointestinal", tip: "The digestive tract, from mouth and esophagus through stomach and intestines to the rectum and anus.", more: "Its studies are the ones that need contrast and motion: barium swallowed or given as an enema, fluoroscopy to watch it move, and an abdominal series for obstruction or free air. The liver, gallbladder, and pancreas sit alongside the tract and are imaged with it." },
  "GSDF": { full: "Grayscale standard display function", tip: "The DICOM display calibration curve that makes the same image look the same on every monitor.", more: "Diagnostic monitors are calibrated to it and checked against test patterns, because a reading station that drifts changes what a radiologist can see. It is part of the display quality control schedule, not a one-time setup." },
  "HIPAA": { full: "Health Insurance Portability and Accountability Act", tip: "The United States law protecting patient information, with privacy, security, and breach rules.", more: "Every image, worklist, dose report, and service log that carries patient identifiers is covered. For a technician it means minimum necessary access, no shared accounts, sanitizing or documenting devices before they leave the building, and never moving patient data onto personal media." },
  "HITECH": { full: "Health Information Technology for Economic and Clinical Health Act", tip: "The law that strengthened privacy enforcement and added breach notification.", more: "It made business associates, including service vendors with remote access, directly liable, and it requires notification to individuals and the government after a breach. Vendor access agreements and access logs exist because of it." },
  "HL7": { full: "Health Level Seven", tip: "The text messaging standard that joins scheduling, chart, and imaging systems.", more: "Orders, admissions, and results travel as structured messages through an interface engine, each one acknowledged by the receiver. When worklists stop appearing on every modality at once, the queue in that engine is the place to look." },
  "HLD": { full: "High-level disinfection", tip: "The level of reprocessing required for a probe that touches mucous membranes.", more: "Items entering sterile tissue are sterilized, items touching mucous membranes get high-level disinfection, and items touching intact skin get low-level disinfection. Using a chemical a probe is not rated for, or soaking it past its immersion line, destroys the probe." },
  "HTM": { full: "Healthcare technology management", tip: "The department and the discipline that manage clinical equipment across its life.", more: "It covers incoming inspection, maintenance strategy, repair, recalls, risk, replacement planning, and the records that prove all of it. Imaging service sits inside it, often as a specialist group." },
  "HU": { full: "Heat unit, and Hounsfield unit", tip: "Two different units with one abbreviation: thermal loading on a tube, and density in a computed tomography image.", more: "As a heat unit it measures thermal loading on an anode: kVp x mA x s on a single-phase system, and 1.4 x kVp x mA x s on a three-phase or high-frequency system, where one unit equals 1.4 joules. Rating charts and anode and housing cooling curves are drawn in these units.\n\nAs a Hounsfield unit it is the density scale of a computed tomography image, running from -1000 to +3000: air is -1000, water is exactly 0 by continuous calibration, and dense bone is about +3000. Which one a question means is always clear from whether it is talking about loading a tube or reading an image." },
  "HVL": { full: "Half-value layer", tip: "The thickness of aluminum that cuts beam intensity in half; the practical measure of beam quality.", more: "It is measured by adding calibrated aluminum sheets until intensity halves, and it rises with kVp and with filtration. Because the layers of a tube's filtration cannot be measured individually, meeting the minimum value for the operating kVp and waveform is how adequate filtration is proven." },
  "ICMP": { full: "Internet Control Message Protocol", tip: "The protocol that carries the echo requests and replies a ping uses.", more: "Some networks block it for security, so a device that will not answer a ping is not automatically down. When that happens, test the application path instead, for example with a DICOM verification." },
  "IEC": { full: "International Electrotechnical Commission", tip: "The body behind IEC 60601-1, the safety standard for medical electrical equipment.", more: "It sets the applied part types and the leakage limits a safety analyzer tests against: earth leakage 5 mA normal and 10 mA single fault, touch current 100 and 500 microamps, type B and BF patient leakage 100 and 500 microamps, type CF 10 and 50 microamps. IEC 80001 covers risk management for networks carrying medical devices." },
  "IP": { full: "Internet Protocol", tip: "The addressing scheme that identifies every device on a network.", more: "Four numbers from 0 to 255 name the device, the subnet mask splits that address into network and host, and the default gateway is the way out of the subnet. Imaging equipment usually keeps a fixed address so it stays reachable." },
  "IT": { full: "Information technology", tip: "The department that owns the network, servers, and security an imaging department depends on.", more: "Imaging work crosses into their territory constantly: addresses, ports, firewall rules, patching schedules, and segmentation. Escalate with facts rather than symptoms: the device, the test you ran, the result, and when it started." },
  "LAN": { full: "Local area network", tip: "The network inside one building or campus, where modalities and archives usually sit together.", more: "Bandwidth inside it is cheap, which is why large studies move quickly between a modality and its archive. When retrievals of prior studies are slow but local transfers are fast, the problem is the link between sites, not the modality." },
  "LAO": { full: "Left anterior oblique", tip: "An oblique position with the left front of the body against the receptor.", more: "Oblique positions put the body between frontal and lateral to open structures that overlap in either. The tube and receptor stay square to each other while the patient rotates, so centering and detents matter more than beam angle." },
  "LED": { full: "Light-emitting diode", tip: "A diode that emits light; the indicator and display backlight of almost every console and panel.", more: "Indicators are the cheapest diagnostic information on a machine, but an unlit one means the circuit driving it is dead or the lamp is, so prove which before concluding anything. In a collimator, a failed lamp invites an uncollimated field, which makes it a dose problem." },
  "LPO": { full: "Left posterior oblique", tip: "An oblique position with the left back of the body against the receptor.", more: "Posterior obliques are taken from a supine or semi-supine patient, so they are common in trauma and portable work where turning the patient fully is not possible." },
  "MDS2": { full: "Manufacturer Disclosure Statement for Medical Device Security", tip: "The standard form that says what a device stores, how it authenticates, and how it can be patched.", more: "Ask for it before a purchase and keep it with the device record: it tells you whether there is patient data on board, whether accounts can be unique, whether antivirus is allowed, and what the vendor's patch commitment is. It is the starting point for segmenting a device that cannot be secured any other way." },
  "MF": { full: "Magnification factor", tip: "Image size divided by object size, equal to the source-to-image distance divided by the source-to-object distance.", more: "Every radiograph magnifies a little: about 1.1 at a 100 cm source-to-image distance and about 1.05 at 180 cm. Magnification grows with object-to-image distance, which is why a long distance blurs detail and why the air gap technique trades sharpness for scatter rejection." },
  "MPPS": { full: "Modality performed procedure step", tip: "The DICOM service by which a modality reports that an exam started, finished, or was discontinued.", more: "Those messages drive status boards, technologist workflow, and billing triggers, so a modality that images perfectly but never reports status creates complaints that sound like missing exams." },
  "MQSA": { full: "Mammography Quality Standards Act", tip: "The federal law that sets mammography accreditation, inspection, personnel, and quality control requirements.", more: "Under it a facility must be accredited, inspected annually, surveyed by a medical physicist annually, and run a written quality control program with daily, weekly, monthly, quarterly, and semiannual tasks. It is the one modality where the quality control schedule itself is law." },
  "MR": { full: "Magnetic resonance", tip: "Imaging from the magnetic behavior of tissue in a strong field; also the labeling scheme for magnet room safety.", more: "Everything taken near the magnet is labeled MR Safe, MR Conditional, or MR Unsafe, and conditional items carry the field, gradient, and radiofrequency limits they were tested to. Test equipment and carts are labeled the same way, which is why a meter cannot simply be carried into the magnet room." },
  "MRI": { full: "Magnetic resonance imaging", tip: "A superconducting magnet, gradient coils, and radiofrequency coils; no ionizing radiation and the field is always on.", more: "Field strength is measured in tesla, and 1 T equals 10,000 gauss. The technician's service list is the cold chain of compressor, cold head, and chiller, the coils and cables, table motion, shielded room integrity, and the computers and network links." },
  "MTBF": { full: "Mean time between failures", tip: "The average interval between one failure of a device and the next; the headline number of a performance report.", more: "It is only as honest as the work orders it is computed from, which is one reason every call gets closed properly. A model whose interval is falling while the fleet's is steady is the argument for replacement, and a device far below its model's average usually has an environment or a use problem rather than a design one." },
  "MWL": { full: "Modality worklist", tip: "The DICOM query that pulls scheduled patients and accession numbers onto the modality console.", more: "It removes hand typing, which removes mismatched identifiers and orphaned studies. When every modality loses its worklist at the same moment, the fault is upstream in the scheduling system or the interface engine, not in the rooms." },
  "NCRP": { full: "National Council on Radiation Protection and Measurements", tip: "The body whose recommended dose limits and shielding reports are adopted into law and used by physicists.", more: "Its dose limit table is the one to memorize: occupational effective dose 50 mSv per year, cumulative 10 mSv times age, lens of the eye 150 mSv, thyroid, skin, hands, and feet 500 mSv, public 1 mSv for frequent exposure, and 0.5 mSv in any month to a declared embryo or fetus." },
  "NEMA": { full: "National Electrical Manufacturers Association", tip: "The manufacturers' standards association behind focal spot tolerances and the home of the imaging communications standard.", more: "Its standards are why a nominal focal spot size comes with an allowed measured range, so a 0.3 mm spot measuring 0.45 mm can still be within specification." },
  "NFPA": { full: "National Fire Protection Association", tip: "The source of NFPA 99 for health care facilities and NFPA 70, the national electrical code.", more: "NFPA 99 gives the numbers a technician tests against: ground resistance 0.5 ohm maximum for patient-care equipment, chassis leakage 500 microamps in current editions, and the patient care vicinity of about 6 feet beyond the bed and 7.5 feet above the floor." },
  "NIC": { full: "Network interface card", tip: "The network adapter and its link light, the first physical check in any connection fault.", more: "No link light means a cable, port, or adapter problem before it means anything else. A link light with no traffic points at addressing, a wrong virtual network on the switch port, or a blocked path." },
  "NRC": { full: "Nuclear Regulatory Commission", tip: "The agency that licenses byproduct radioactive material, which is why nuclear medicine has its own rules.", more: "Its licence conditions cover surveys, record keeping, waste, and who may handle material. A technician servicing a gamma camera works inside those rules even though the equipment itself is not the licensed item." },
  "NaI": { full: "Sodium iodide", tip: "The scintillation crystal in a gamma camera, which flashes light when a gamma ray is absorbed.", more: "Thallium-activated sodium iodide is large, efficient at gamma energies, and fragile: it cracks from mechanical shock and from rapid temperature change, so the detector head is moved and stored with care." },
  "OID": { full: "Object-to-image receptor distance", tip: "The gap between the anatomy and the receptor; the main driver of magnification and blur.", more: "Keeping it short keeps the image sharp, which is why compression in mammography improves detail as well as contrast. Lengthening it deliberately is the air gap technique, letting scatter miss the receptor instead of using a grid." },
  "ORM": { full: "Order message", tip: "The message type that carries a clinical order from the chart to the scheduling and imaging systems.", more: "An order that never arrives means no worklist entry and an exam that cannot be started cleanly. That is an interface problem, which is why the engine queue is the first place to look." },
  "ORU": { full: "Observation result message", tip: "The message type that returns a result or report to the chart.", more: "An exam can be performed and read correctly while the report never lands, because that final message failed. Clinicians experience it as a missing result, so the complaint arrives sounding like an imaging fault." },
  "OSHA": { full: "Occupational Safety and Health Administration", tip: "The United States agency for worker safety: hazard communication, bloodborne pathogens, electrical practice, and PPE.", more: "It regulates the technician's own safety rather than the patient's: lockout and tagout before opening a cabinet, exposure control for blood and body fluids, and the protective equipment the employer must supply and train on." },
  "OSL": { full: "Optically stimulated luminescence", tip: "A personal dosimeter type read out by stimulating the detector with light.", more: "It can be re-read, is sensitive at low doses, and like a thermoluminescent badge is returned to a service for reading. Whatever the type, the badge is worn at the collar outside the apron during fluoroscopy." },
  "PA": { full: "Posteroanterior", tip: "A projection in which the beam enters the back of the body and exits the front.", more: "The patient faces the receptor, which puts the anatomy of interest closer to it and reduces magnification. The standard erect chest image is taken this way." },
  "PACS": { full: "Picture archiving and communication system", tip: "The archive plus the reading workstations: it stores, retrieves, distributes, and displays images.", more: "When it is down, every reading station and every prior-study retrieval fails while the modalities keep scanning into their local queues, so local disk space becomes the clock you are working against. That is why its backups and restore tests matter as much as its uptime." },
  "PBL": { full: "Positive beam limitation", tip: "Automatic collimation that sizes the shutters to the receptor in use.", more: "It must stay accurate within 2 percent of the source-to-image distance at every standard distance and receptor size. No longer federally required but still fitted to most new rooms, it is a quality control item wherever it exists." },
  "PDU": { full: "Power distribution unit", tip: "The panel inside a system that takes the incoming feed and splits it to the subsystems.", more: "One feed usually serves the generator, the gantry or table, the console, and the computers, so a single failed branch or blown branch fuse can look exactly like total power failure. Finding which branches are alive is the first split in any dead-system call." },
  "PET": { full: "Positron emission tomography", tip: "Imaging that counts pairs of photons emitted in opposite directions when a positron annihilates with an electron.", more: "Each photon of the pair carries about 0.51 MeV, and the detector ring records only coincident pairs, which is what locates the event. It is usually built as a hybrid with computed tomography, so every service item of a scanner comes with it." },
  "PHI": { full: "Protected health information", tip: "Patient-identifiable information in any form, including what sits in consoles, caches, and service logs.", more: "Images, worklists, dose reports, and error logs can all carry identifiers. Sanitize or document a device before it leaves the building, keep service accounts separate from clinical ones, and never move this data onto personal media." },
  "PING": { full: "Packet internet groper", tip: "The command that sends echo requests to an address to prove the path and the host are alive.", more: "Work outward: the device's own address, then the gateway, then the archive by address, then the archive by name. Each step that works narrows the fault, and the first that fails names the layer to investigate." },
  "PM": { full: "Preventive maintenance", tip: "Scheduled inspection, testing, and service meant to find problems before a patient or a schedule does.", more: "On imaging equipment it covers mechanical safety, electrical safety, interlocks, radiation output, error logs, cleaning, and documentation. The completion rate is one of the first numbers an accreditation surveyor asks for." },
  "PMT": { full: "Photomultiplier tube", tip: "A tube that turns a faint light flash into a measurable electrical pulse.", more: "An array of them behind a scintillation crystal locates each event and measures its energy, which is how a gamma camera forms an image. They drift with age and temperature, so uniformity correction and energy peaking are routine quality control." },
  "PPE": { full: "Personal protective equipment", tip: "The gowns, gloves, eye protection, and respirators a task requires, plus the lead a radiation task requires.", more: "In imaging it covers both infection control and radiation: an apron, thyroid shield, and mobile barrier are the radiation side. The employer must supply it, train on it, and maintain it, and aprons must be imaged for cracks at least annually." },
  "PSP": { full: "Photostimulable phosphor", tip: "The storage phosphor in a computed radiography plate that holds a latent image until a laser releases it.", more: "The plate traps energy from the exposure, a scanning laser stimulates it to glow in proportion to that trapped energy, and a bright lamp erases what remains. The plate is reusable, so its physical condition becomes part of image quality." },
  "QC": { full: "Quality control", tip: "The scheduled measurements that prove an imaging system still performs within tolerance.", more: "Its tolerances are worth memorizing: kVp within 10 percent, timer within 5 percent above 10 ms, linearity within 10 percent between adjacent stations, reproducibility within plus or minus 5 percent, and light and radiation fields coinciding within 2 percent of the distance." },
  "RAO": { full: "Right anterior oblique", tip: "An oblique position with the right front of the body against the receptor.", more: "It is the common oblique for barium studies of the esophagus and stomach, so the fluoroscopic table detents and the tube and receptor alignment through the rotation are what matter to the equipment side." },
  "RC": { full: "Resistor-capacitor (circuit)", tip: "A resistor and a capacitor together, whose time constant is the resistance times the capacitance.", more: "A capacitor charging through a resistor reaches about 63 percent of the final voltage in one time constant and about 99 percent after five, and discharge follows the same curve. That is why a bleeder resistor's value tells you how long a cabinet needs before it is safe to open, and why timing and filter circuits are built from these two parts." },
  "RF": { full: "Radiofrequency", tip: "The radio part of the spectrum: the transmit and receive energy of magnetic resonance and a common source of interference.", more: "In a magnet room it is both a tool and a hazard, because deposited energy heats tissue and looped or damaged cables cause burns. The copper shielding and filter panel of the room exist to keep outside radiofrequency out and the room's own energy in." },
  "RIS": { full: "Radiology information system", tip: "The department system that schedules exams, holds the worklist, tracks status, and routes reports.", more: "It sits between the chart and the imaging equipment: the order arrives from the chart, the worklist goes out to the modality, status comes back, and the report returns to the chart. Knowing that order is how you judge how wide a fault is." },
  "RJ45": { full: "Eight-position modular connector", tip: "The familiar eight-pin plug on a twisted pair network cable.", more: "A miswired or loose one is a layer 1 fault that shows up as an intermittent link or a link that negotiates at the wrong speed. A tester that proves the wire map end to end settles it in seconds." },
  "RMS": { full: "Root mean square", tip: "The effective value of an alternating voltage: 0.707 times the peak.", more: "Mains stated as 120 V is an effective value whose peak is about 170 V, which is why insulation and components must be rated well above the stated figure. Multiply the effective value by 1.414 to get the peak." },
  "RPO": { full: "Right posterior oblique", tip: "An oblique position with the right back of the body against the receptor.", more: "Like the left posterior oblique it is taken from a supine or semi-supine patient, so it appears constantly in trauma and bedside work." },
  "RSO": { full: "Radiation safety officer", tip: "The person who owns a facility's radiation safety program and can stop unsafe practice.", more: "The role covers the dosimetry program and its badge reports, area surveys, postings and signage, incident and overexposure investigation, and training. The radiation safety committee that officer reports to reviews dose trends, shielding designs, new equipment, and room changes, so output measurements and repair records go to both." },
  "SCR": { full: "Silicon controlled rectifier", tip: "A gate-triggered solid-state switch used to control alternating current power.", more: "It conducts once its gate is triggered and stops when the current passes through zero, which makes it the usual switching element in generator primary circuits and rotor drives. A shorted one passes power continuously and an open one passes nothing, so measure both sides before blaming the control board." },
  "SDS": { full: "Safety data sheet", tip: "The standard document for a chemical: its hazards, handling, protective equipment, and first aid.", more: "Hazard communication rules require a label on the container and this sheet available where the work happens, with training on both. In imaging the chemicals are cleaners and high-level disinfectants, contrast agents, cryogens, and battery electrolyte, and the sheet is what tells you the protective equipment and the spill response for each." },
  "SI": { full: "International System of Units", tip: "The metric system the modern radiation units belong to: gray, sievert, and becquerel.", more: "Older units persist in conversation and on older equipment, so know the conversions cold: 1 Gy equals 100 rad, 1 Sv equals 100 rem, and 1 R equals 2.58 x 10 to the minus 4 C/kg." },
  "SID": { full: "Source-to-image receptor distance", tip: "The distance from focal spot to receptor; standard distances are 100 cm and 180 cm.", more: "Several federal tolerances are written as a percentage of it: the light field must match the radiation field within 2 percent, automatic collimation must hold 2 percent, and the distance indicator itself must be accurate within 2 percent. At a 100 cm distance, 2 percent is 2 cm." },
  "SOD": { full: "Source-to-object distance", tip: "The distance from focal spot to the anatomy being imaged.", more: "Together with the object-to-receptor distance it sets magnification and focal spot blur: blur equals the effective focal spot size times the object-to-receptor distance divided by this distance." },
  "SOP": { full: "Service-object pair", tip: "The DICOM pairing of a service with an information object, which says what a node can actually do.", more: "The classes a node supports are negotiated when the association opens. A receiver that does not support the class a modality is sending is the quiet reason some studies transfer and others do not." },
  "SPECT": { full: "Single photon emission computed tomography", tip: "Nuclear imaging that rotates a gamma camera around the patient to reconstruct slices.", more: "Rotation adds gantry motion, uniformity, and center-of-rotation calibrations to the usual camera quality control. It is often built as a hybrid with computed tomography for attenuation correction and anatomy." },
  "SSD": { full: "Source-to-skin distance", tip: "The distance from focal spot to the patient's skin; the fluoroscopic minimum is a federal limit.", more: "It must be at least 38 cm on a stationary fluoroscope and 30 cm on a mobile one, because entrance dose rises steeply as the tube comes closer. Halving it roughly quadruples the entrance exposure from geometry alone, which is why the spacer must never be removed." },
  "TEE": { full: "Transesophageal echocardiography (probe)", tip: "An ultrasound probe passed down the esophagus to image the heart from behind it.", more: "Because it contacts mucous membranes it needs high-level disinfection between patients, and its long flexible shaft fails at the bend points. Leak testing before reprocessing is what keeps fluid out of the electronics." },
  "TFT": { full: "Thin-film transistor", tip: "The transistor array on a flat panel detector that reads out each pixel's charge.", more: "One array holds a transistor and a storage capacitor per pixel, which is how a whole detector is read in a fraction of a second. Dead rows or columns in that array show as straight lines that the defective pixel map hides until it is out of date." },
  "TJC": { full: "The Joint Commission", tip: "An accrediting organization that surveys hospitals on behalf of the federal payer.", more: "Its environment of care standards are where equipment questions land: a complete inventory, a documented maintenance strategy, completion rates, test records, and inspection history. It is one of several organizations with that deeming authority." },
  "TLD": { full: "Thermoluminescent dosimeter", tip: "A personal dosimeter read out by heating the crystal and measuring the light it gives off.", more: "It is rugged, tissue-equivalent, and read by a service that reports accumulated dose, but reading it erases it. Worn at the collar outside the apron during fluoroscopy, it is the record of occupational dose against the annual limits." },
  "Tc": { full: "Technetium", tip: "The element behind technetium-99m, the workhorse tracer of nuclear medicine.", more: "Technetium-99m decays to technetium-99 with a 140 keV gamma ray, which is the energy window a gamma camera is peaked for. It is generated on site, which is why the dose calibrator and its own quality control sit in the hot lab." },
  "UPS": { full: "Uninterruptible power supply", tip: "A battery-backed supply that carries a load through a power failure.", more: "Online double-conversion units always run the load from the inverter and give the cleanest protection for consoles, archives, and workstations; line-interactive units regulate and switch on loss; standby units only switch. Batteries age out, so a unit nobody has load-tested is not protection." },
  "VAC": { full: "Volts alternating current", tip: "A voltage reading on the alternating supply side of equipment.", more: "Single-phase service is 120/240 at 60 Hz; imaging rooms are commonly designed for 220 and some for 110 or 440, with three-phase service feeding the larger generators. Always confirm what a room is actually fed before connecting test gear." },
  "VDC": { full: "Volts direct current", tip: "A voltage reading on a direct current rail inside equipment.", more: "Logic, interface, and interlock boards run from low-voltage rails inside the cabinet. Measure each rail at the test point the manual names before condemning a board, because a sagging supply imitates a dozen different faults." },
  "VLAN": { full: "Virtual local area network", tip: "A logical network carved out of shared switches, often used to separate imaging equipment.", more: "Devices on different virtual networks cannot reach each other without a router, so a perfectly good cable in the wrong port gets nowhere. Segmenting devices that cannot be patched is the standard way to protect them." },
  "VNA": { full: "Vendor neutral archive", tip: "An archive that stores studies from many systems in a standard form.", more: "Because the data is not locked to one vendor's format, a modality or reading system can be replaced without migrating everything again. It is also where enterprise image management, retention, and lifecycle rules usually live." },
  "VPN": { full: "Virtual private network", tip: "An encrypted tunnel; the controlled way a vendor reaches equipment from outside.", more: "Remote service should come through a tunnel the hospital controls, with a named account, logging, and a time limit, never an always-on modem or an unknown tunnel out of the building. Shut the account when the visit ends." },
  "WAN": { full: "Wide area network", tip: "The network joining sites, usually over links leased from a carrier.", more: "Bandwidth between buildings costs money, so it is where slow prior-study retrievals and slow remote reading usually live. Proving local transfers are fast before escalating saves the department an argument." },
  "kVA": { full: "Kilovolt-ampere", tip: "A thousand volt-amperes: the apparent power a supply must be able to deliver.", more: "It is the rating on a generator's nameplate that sizes the feeder, the breaker, and the disconnect, and it is larger than the real power in kilowatts because current and voltage are not perfectly in step. Comparing the nameplate figure with what the room is actually fed is the first check on any installation or relocation." },
  "kVp": { full: "Kilovolt peak", tip: "The highest voltage across the tube during an exposure; it sets beam quality and strongly affects quantity.", more: "Quality means penetrability, measured as half-value layer. Quantity rises with roughly the square of this value, which is why raising it 15 percent is equivalent to doubling the exposure, and why the 15 percent rule pairs that rise with halving the milliampere seconds." },
  "mA": { full: "Milliampere", tip: "Tube current: the number of electrons crossing from filament to target each second.", more: "It is set by filament heating and is linear with x-ray quantity, so doubling it doubles the number of photons without changing their energies. Adjacent stations must agree within 10 percent, which is what the linearity test proves." },
  "mAs": { full: "Milliampere seconds", tip: "Tube current multiplied by exposure time: the single number that sets how many x-rays are made.", more: "Any combination of current and time that gives the same product should give the same receptor exposure, which is the reciprocity the quality control linearity test checks. It is also the unit the automatic exposure control backup limit of 600 is written in." }
};
// Uppercase words in the course text that are not acronyms (emphasis, roman numerals, meter displays).
FRA.acronymIgnore = ["BEST", "FIRST", "II", "III", "IV", "LEAST", "MOST", "NOT", "OFF", "OL"];
